                var = random.randint(1, n)
                if var not in clause:
                    clause.add(var)
            clauses.append(tuple(sorted(clause)))
        return clauses

    def symplectic_leaf_decomposition(clauses):
        leaves = set()
        for clause in clauses:
            leaves.update(clause)
        return len(leaves)

    def communication_complexity_rank_variance(clauses):
        n_vars = max(max(clause) for clause in clauses)
        matrix = [[0] * (n_vars + 1) for _ in range(n_vars + 1)]
        for clause in clauses:
            for i in range(len(clause)):
                for j in range(i + 1, len(clause)):
                    matrix[clause[i]][clause[j]] += 1
                    matrix[clause[j]][clause[i]] += 1

        def gaussian_elimination(A):
            n = len(A)
            for i in range(n):
                max_row = i
                for j in range(i + 1, n):
                    if abs(A[j][i]) > abs(A[max_row][i]):
                        max_row = j
                A[i], A[max_row] = A[max_row], A[i]

                pivot = A[i][i]
                for j in range(n):
                    A[i][j] /= pivot

                for j in range(n):
                    if j != i:
                        factor = A[j][i]
                        for k in range(n):
                            A[j][k] -= factor * A[i][k]

            return [A[i][i] for i in range(n)]

        rank_variance = sum(gaussian_elimination(matrix)) / n_vars
